import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import api from 'lib/api'
import { createFeaturePreviewSearch } from 'lib/utils/fuseSearch'
import { urls } from 'scenes/urls'

import { Breadcrumb, EarlyAccessFeatureAssignee, EarlyAccessFeatureType } from '~/types'

const search = createFeaturePreviewSearch<EarlyAccessFeatureType>()

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface earlyAccessFeaturesLogicValues {
    breadcrumbs: Breadcrumb[]
    earlyAccessFeatures: EarlyAccessFeatureType[]
    earlyAccessFeaturesLoading: boolean
    filteredEarlyAccessFeatures: EarlyAccessFeatureType[]
    searchTerm: string
    waitlistResponsesCount: Record<string, number>
    waitlistResponsesCountLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface earlyAccessFeaturesLogicActions {
    loadEarlyAccessFeatures: () => any
    loadEarlyAccessFeaturesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadEarlyAccessFeaturesSuccess: (
        earlyAccessFeatures: EarlyAccessFeatureType[],
        payload?: any
    ) => {
        earlyAccessFeatures: EarlyAccessFeatureType[]
        payload?: any
    }
    loadWaitlistResponsesCount: (surveyIds: string) => string
    loadWaitlistResponsesCountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadWaitlistResponsesCountSuccess: (
        waitlistResponsesCount: {
            [key: string]: number
        },
        payload?: string
    ) => {
        waitlistResponsesCount: {
            [key: string]: number
        }
        payload?: string
    }
    setSearchTerm: (searchTerm: string) => {
        searchTerm: string
    }
    updateFeatureAssignee: (
        id: EarlyAccessFeatureType['id'],
        assignee: EarlyAccessFeatureAssignee | null
    ) => {
        assignee: EarlyAccessFeatureAssignee | null
        id: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface earlyAccessFeaturesLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        filteredEarlyAccessFeatures: (
            earlyAccessFeatures: EarlyAccessFeatureType[],
            searchTerm: string
        ) => EarlyAccessFeatureType[]
    }
}

export type earlyAccessFeaturesLogicType = MakeLogicType<
    earlyAccessFeaturesLogicValues,
    earlyAccessFeaturesLogicActions,
    Record<string, any>,
    earlyAccessFeaturesLogicMeta
>

export const earlyAccessFeaturesLogic = kea<earlyAccessFeaturesLogicType>([
    path(['products', 'earlyAccessFeatures', 'frontend', 'earlyAccessFeaturesLogic']),

    actions({
        setSearchTerm: (searchTerm: string) => ({ searchTerm }),
        updateFeatureAssignee: (id: EarlyAccessFeatureType['id'], assignee: EarlyAccessFeatureAssignee | null) => ({
            id,
            assignee,
        }),
    }),

    loaders({
        earlyAccessFeatures: {
            __default: [] as EarlyAccessFeatureType[],
            loadEarlyAccessFeatures: async () => {
                const response = await api.earlyAccessFeatures.list()
                return response.results
            },
        },
        waitlistResponsesCount: {
            __default: {} as Record<string, number>,
            loadWaitlistResponsesCount: async (surveyIds: string) => {
                try {
                    return await api.surveys.getResponsesCount(surveyIds)
                } catch {
                    // Fail soft: users without survey access should still get the features list
                    return {}
                }
            },
        },
    }),

    reducers({
        searchTerm: [
            '',
            {
                setSearchTerm: (_, { searchTerm }) => searchTerm,
            },
        ],
        earlyAccessFeatures: {
            updateFeatureAssignee: (state, { id, assignee }) =>
                state.map((feature) => (feature.id === id ? { ...feature, assignee } : feature)),
        },
    }),

    selectors({
        breadcrumbs: [
            () => [],
            (): Breadcrumb[] => [
                {
                    key: 'EarlyAccessFeatures',
                    name: 'Early access features',
                    path: urls.earlyAccessFeatures(),
                    iconType: 'early_access_feature',
                },
            ],
        ],

        filteredEarlyAccessFeatures: [
            (s) => [s.earlyAccessFeatures, s.searchTerm],
            (earlyAccessFeatures: EarlyAccessFeatureType[], searchTerm: string): EarlyAccessFeatureType[] => {
                return search(earlyAccessFeatures, searchTerm)
            },
        ],
    }),

    listeners(({ actions }) => ({
        loadEarlyAccessFeaturesSuccess: ({ earlyAccessFeatures }) => {
            const surveyIds = earlyAccessFeatures
                .map((feature) => feature.payload?.survey_id)
                .filter((id): id is string => typeof id === 'string')
            if (surveyIds.length > 0) {
                actions.loadWaitlistResponsesCount(surveyIds.join(','))
            }
        },
        updateFeatureAssignee: async ({ id, assignee }) => {
            try {
                await api.earlyAccessFeatures.update(id, { assignee })
            } catch {
                lemonToast.error('Failed to update assignee')
                // Reload to revert the optimistic update
                actions.loadEarlyAccessFeatures()
            }
        },
    })),

    afterMount(({ actions }) => {
        actions.loadEarlyAccessFeatures()
    }),
])
